// The search-index writer worker (worker_threads entry point).
//
// node:sqlite is synchronous, so index writes — above all the initial backfill
// that reads EVERY agent's store.db and rebuilds the FTS tables — would block
// the host event loop (gateway, in-flight turns) if they ran on the host
// thread. The host's SandSearchIndexService posts every index mutation here
// instead; this thread is the index's single writer, applying jobs strictly in
// post order. The host keeps its own read-only connection for queries, which
// WAL lets run beside these writes without blocking.
//
// MESSAGE-DRIVEN like box-store-vacuum-worker: the worker stays alive on its
// `message` listener until the host terminates it, and every job is acked by
// requestId so a clean `exit` can never race ahead of a result and be misread
// as a failure.
//
// Emitted as CJS (extensions/content-search/search-index-worker.cjs) with the same NODE_PATH
// banner as the other host workers (scripts/build-main.mjs) and copied into
// the shipped host bundle (box/build/build-sand-host-bundle.sh), so it resolves the
// externalized node:sqlite the same way when spawned by the host.

import { parentPort, workerData } from "node:worker_threads";

import { invariant } from "../../../shared/invariant.js";
import { isSqliteCorruptError } from "../../storage/sqlite-busy.js";
import { ensureSearchIndexSchema, openSearchIndexDb } from "./search-index-db.js";
import type {
	SearchIndexWorkerConfig,
	SearchIndexWorkerRequest,
	SearchIndexWorkerResponse,
} from "./search-index-protocol.js";
import { SandSearchIndexWriter } from "./search-index-writer.js";

const port = parentPort;
invariant(port != null, "search-index-worker must run as a worker_thread");

const config = workerData as SearchIndexWorkerConfig;
invariant(
	typeof config?.indexDbPath === "string" && typeof config?.agentsRootDir === "string",
	"search-index-worker needs indexDbPath + agentsRootDir",
);

const db = openSearchIndexDb(config.indexDbPath);
ensureSearchIndexSchema(db);
const writer = new SandSearchIndexWriter(db, config.agentsRootDir);

port.on("message", (request: SearchIndexWorkerRequest) => {
	let response: SearchIndexWorkerResponse;
	try {
		writer.runJob(request.job);
		response = { requestId: request.requestId, ok: true };
	} catch (error) {
		response = {
			requestId: request.requestId,
			ok: false,
			message: error instanceof Error ? error.message : String(error),
			isIndexCorrupt: isSqliteCorruptError(error),
		};
	}
	port.postMessage(response);
});
