// SAFETY: reveal-only; pins "reveals (never opens) when the extension is unknown, hidden, or absent".
export const INERT_OPENABLE_ATTACHMENT_EXTENSIONS: ReadonlySet<string> = new Set([
	"txt",
	"md",
	"markdown",
	"log",
	"json",
	"yaml",
	"yml",
	"toml",
	"csv",
	"png",
	"jpg",
	"jpeg",
	"gif",
	"webp",
	"svg",
	"pdf",
]);

// "open": reveal in folder OR open with the default app. "reveal": the OS
// file manager only, never an OS opener.
export type AttachmentOpenAction = "open" | "reveal";

// Lower-case extension without the dot, or null. A leading dot (dotfiles
// like `.gitignore`) or a trailing dot is treated as no extension, matching
// the card's own `splitFileName`.
export function attachmentExtension(nameOrPath: string): string | null {
	const segments = nameOrPath.split(/[/\\]/);
	const base = segments[segments.length - 1] ?? "";
	const dot = base.lastIndexOf(".");
	if (dot <= 0 || dot === base.length - 1) return null;
	return base.slice(dot + 1).toLowerCase();
}

export function isInertOpenableAttachment(nameOrPath: string): boolean {
	if (typeof nameOrPath !== "string" || nameOrPath.length === 0) return false;
	const ext = attachmentExtension(nameOrPath);
	return ext != null && INERT_OPENABLE_ATTACHMENT_EXTENSIONS.has(ext);
}

// The gate both processes share: a default-app open is permitted only for an
// allowlisted inert type; everything else is reveal-only.
export function attachmentOpenAction(nameOrPath: string): AttachmentOpenAction {
	return isInertOpenableAttachment(nameOrPath) ? "open" : "reveal";
}
