import type { SandMessageMatchRole } from "../../../shared/search.js";
import {
	isHiddenOutboundAgentPeerMessageEntry,
	type SandTranscriptEntry,
} from "../../../shared/transcript.js";
import type { SandTranscriptMatch } from "../../extensions/content-search/api.js";

export const AGENT_CONTENT_SEARCH_MAX_MATCHES_PER_AGENT = 5;
export const AGENT_CONTENT_SEARCH_MAX_RESULTS = 50;

const SNIPPET_LEAD = 30;
const SNIPPET_TRAIL = 60;
const ELLIPSIS = "…";

export function entrySearchText(entry: SandTranscriptEntry): string {
	switch (entry.kind) {
		case "message":
			return entry.content;
		case "send-message":
			return entry.message.type === "text" ? entry.message.content : "";
		case "notice":
			return entry.text;
		default:
			return "";
	}
}

function entryRole(entry: SandTranscriptEntry): SandMessageMatchRole {
	return entry.kind === "message" ? entry.role : "assistant";
}

function flatten(text: string): string {
	return text.replace(/\s+/g, " ").trim();
}

export function buildContentSnippet(text: string, normalizedQuery: string): string | null {
	if (normalizedQuery.length === 0) return null;
	const flat = flatten(text);
	const index = flat.toLowerCase().indexOf(normalizedQuery);
	if (index < 0) return null;
	const start = Math.max(0, index - SNIPPET_LEAD);
	const end = Math.min(flat.length, index + normalizedQuery.length + SNIPPET_TRAIL);
	const core = flat.slice(start, end);
	const prefix = start > 0 ? ELLIPSIS : "";
	const suffix = end < flat.length ? ELLIPSIS : "";
	return `${prefix}${core}${suffix}`;
}

export function findAgentContentMatches(
	entries: readonly SandTranscriptEntry[],
	normalizedQuery: string,
	limit = AGENT_CONTENT_SEARCH_MAX_MATCHES_PER_AGENT,
): readonly SandTranscriptMatch[] {
	if (normalizedQuery.length === 0) return [];
	const matches: SandTranscriptMatch[] = [];
	for (let i = entries.length - 1; i >= 0; i--) {
		if (matches.length >= limit) break;
		const entry = entries[i];
		if (entry == null) continue;
		if (isHiddenOutboundAgentPeerMessageEntry(entry)) continue;
		const snippet = buildContentSnippet(entrySearchText(entry), normalizedQuery);
		if (snippet == null) continue;
		matches.push({
			entryId: entry.id,
			role: entryRole(entry),
			timestampMs: entry.timestampMs ?? 0,
			snippet,
		});
	}
	return matches;
}
