import { delay } from "../../shared/node/async.js";

// node:sqlite surfaces a lock as ERR_SQLITE_ERROR carrying the numeric SQLite
// result code (errcode) and a "database is locked" message. We match on both so
// the check still holds if a future runtime exposes only one of them.
interface SqliteResultError extends Error {
	readonly code?: string;
	readonly errcode?: number;
}

// SQLite result codes for a contended db (see sqlite3.h): SQLITE_BUSY (5) and
// SQLITE_LOCKED (6). Either means another connection holds a conflicting lock.
const SQLITE_BUSY = 5;
const SQLITE_LOCKED = 6;

export function isSqliteBusyError(error: unknown): boolean {
	if (!(error instanceof Error)) return false;
	const errcode = (error as SqliteResultError).errcode;
	if (errcode === SQLITE_BUSY || errcode === SQLITE_LOCKED) return true;
	const message = error.message.toLowerCase();
	return (
		message.includes("database is locked") ||
		message.includes("database table is locked") ||
		message.includes("database schema is locked")
	);
}

// SQLite primary result code for a disk I/O failure (SQLITE_IOERR). Extended
// codes (e.g. SQLITE_IOERR_SHORT_READ = 522) carry the primary code in their
// low byte, so masking with 0xff catches every IOERR_* variant.
const SQLITE_IOERR = 10;

// A disk-I/O failure. NOT how on-disk WAL damage surfaces: SQLite replays or
// truncates a torn -wal itself on the next open, and node:sqlite reports
// unreadable sidecars or a damaged image as CANTOPEN/CORRUPT. A bare IOERR
// means a transient filesystem fault or stale process-local WAL state, so
// callers retry or surface it — never delete a live db's -wal/-shm on it (the
// -wal holds committed frames, and deleting it under any live same-process
// handle poisons the store's shared WAL state — SAND-1015). Only recovery on
// worker-owned or quarantined copies may reset sidecars.
export function isSqliteIoError(error: unknown): boolean {
	if (!(error instanceof Error)) return false;
	const errcode = (error as SqliteResultError).errcode;
	if (typeof errcode === "number" && (errcode & 0xff) === SQLITE_IOERR) {
		return true;
	}
	const message = error.message.toLowerCase();
	return message.includes("disk i/o error") || message.includes("short read");
}

const SQLITE_CANTOPEN = 14;

export function isSqliteCantOpenError(error: unknown): boolean {
	if (!(error instanceof Error)) return false;
	const errcode = (error as SqliteResultError).errcode;
	if (typeof errcode === "number" && (errcode & 0xff) === SQLITE_CANTOPEN) {
		return true;
	}
	return error.message.toLowerCase().includes("unable to open database");
}

// SQLite primary result codes for a structurally-broken main database file:
// SQLITE_CORRUPT (11) — "database disk image is malformed" — and SQLITE_NOTADB
// (26) — "file is not a database" (a header so damaged SQLite no longer
// recognizes the file). Extended CORRUPT_* codes (SQLITE_CORRUPT_VTAB = 267,
// _SEQUENCE = 523, _INDEX = 779) carry the primary code in their low byte, so
// masking with 0xff catches every variant.
const SQLITE_CORRUPT = 11;
const SQLITE_NOTADB = 26;

export function isSqliteCorruptError(error: unknown): boolean {
	if (!(error instanceof Error)) return false;
	const errcode = (error as SqliteResultError).errcode;
	if (typeof errcode === "number") {
		const primary = errcode & 0xff;
		if (primary === SQLITE_CORRUPT || primary === SQLITE_NOTADB) return true;
	}
	const message = error.message.toLowerCase();
	return (
		message.includes("malformed") ||
		message.includes("is not a database") ||
		message.includes("database disk image")
	);
}

export interface RetrySqliteBusyOptions {
	readonly attempts?: number;
	readonly baseDelayMs?: number;
}

export async function retrySqliteBusy<T>(
	operation: () => Promise<T>,
	options: RetrySqliteBusyOptions = {},
): Promise<T> {
	const attempts = Math.max(1, options.attempts ?? 5);
	const baseDelayMs = options.baseDelayMs ?? 100;
	let lastError: unknown;
	for (let attempt = 0; attempt < attempts; attempt++) {
		try {
			return await operation();
		} catch (error) {
			if (!isSqliteBusyError(error)) throw error;
			lastError = error;
			if (attempt < attempts - 1) {
				await delay(baseDelayMs * 2 ** attempt);
			}
		}
	}
	throw lastError;
}
