// The fast first gate: the renderer picks the card shape (download-only vs
// collapsible preview) synchronously, with no read and so no layout shift.
export function isTextPreviewableName(nameOrPath: string): boolean {
	const ext = attachmentExtension(nameOrPath);
	return ext != null && TEXT_PREVIEWABLE_EXTENSIONS.has(ext);
}

// The same 8 KiB sniff window git uses, plenty to catch an
// archive/executable header.
export const BINARY_SNIFF_BYTE_WINDOW = 8 * 1024;

const BINARY_CONTROL_BYTE_RATIO = 0.3;

// A single NUL byte is decisive (text never contains one); otherwise a high
// ratio of control bytes that are not ordinary whitespace flags binary.
// High bytes (0x80+) are left uncounted since they are normal in UTF-8
// multibyte sequences.
export function looksLikeBinary(bytes: Uint8Array): boolean {
	const sample =
		bytes.byteLength > BINARY_SNIFF_BYTE_WINDOW
			? bytes.subarray(0, BINARY_SNIFF_BYTE_WINDOW)
			: bytes;
	if (sample.byteLength === 0) return false;
	let controlBytes = 0;
	for (const byte of sample) {
		if (byte === 0) return true;
		const isTextWhitespace = byte >= 0x09 && byte <= 0x0d;
		if (byte < 0x20 && !isTextWhitespace) controlBytes += 1;
	}
	return controlBytes / sample.byteLength > BINARY_CONTROL_BYTE_RATIO;
}
