// Transcript entries and the SendMessage payload union: the domain shapes for
// everything a conversation renders and persists. The mutable transcript
// cache stays in main/transcript-store.ts; the zod schemas that PARSE widgets
// stay in shared/sand-widgets.ts and compile-check against the shapes here.

import type { SandListenerPlatform } from "./automations.js";
import type {
	SandLocalToolAction,
	SandLocalToolPermissionStatus,
} from "./local-tool-permission.js";
import type { SandPermissionRequest, SandSecretRequest } from "./requests.js";
import type { SandTimelineEvent } from "./timeline.js";

export type SandWidgetActionStyle = "default" | "primary" | "danger";

export interface SandChoiceOption {
	readonly label: string;
	/** Text sent back when this option is confirmed. Defaults to the label. */
	readonly value?: string | undefined;
	readonly description?: string | undefined;
	readonly style?: SandWidgetActionStyle | undefined;
}

// A single interactive widget: a question with selectable options the user
// picks from and confirms.
export interface SandWidget {
	readonly prompt: string;
	readonly helpText?: string | undefined;
	readonly options: readonly SandChoiceOption[];
	/** When true, the user can type a custom free-text answer instead. */
	readonly allowCustom?: boolean | undefined;
	/**
	 * When true, this widget auto-dismisses (becomes inert, shows a muted
	 * Dismissed state) once the user sends a newer message without answering it.
	 */
	readonly dismissOnMoveOn?: boolean | undefined;
}

export type SandToolCallStatus = "pending" | "done" | "failed";

// An optional channel address (e.g. "slack:C12345") that routes a message to
// an outside platform instead of the in-app Sand chat. Omitted means the
// in-app chat, exactly as before. Only text and attachment messages can target
// a channel; widgets and cursor-agent cards are in-app affordances.
export type SandSendMessageChannel = string;

// An image attached to a text message. It renders INSIDE the text bubble,
// below the prose — one combined card — rather than as the standalone media
// row a `type:"attachment"` message becomes. `alt` follows the standalone
// attachment's contract: hover tooltip + fullscreen caption. The same shape
// rides agent-to-agent messages (SendToAgent images), so a peer exchange
// renders through the exact combined bubble a SendMessage with images uses.
export interface SandSendMessageImage {
	readonly url: string;
	readonly alt?: string;
	readonly width?: number;
	readonly height?: number;
}

export type SandConnectorCardVariant = "connected" | "connect";

export type SandAutoReviewApprovalStatus = "pending" | "approved" | "denied" | "always" | "expired";

export const SAND_AUTO_REVIEW_STALE = "auto-review/stale";
export const SAND_AUTO_REVIEW_STALE_MESSAGE =
	"The Auto-review request is stale, expired, or not authorized.";

/**
 * Host-authored Auto-review card. This variant is intentionally absent from the
 * model-facing SendMessage schema, so an assistant cannot manufacture a consent
 * request or mark one approved.
 */
export interface SandAutoReviewApproval {
	readonly requestId: string;
	readonly surface:
		| "host_shell"
		| "box_shell"
		| "mcp"
		| "computer"
		| "automation_write"
		| "cloud_agent";
	/** Plain-English what the agent is trying to do. */
	readonly summary: string;
	readonly reason: string;
	readonly status: SandAutoReviewApprovalStatus;
	/**
	 * Exact command/payload for the expand affordance. When absent, the
	 * summary itself is what expands (legacy / non-shell surfaces).
	 */
	readonly command?: string;
	readonly proposedRule?: string;
}

export function settlePendingAutoReviewApprovalEntry(
	entry: SandTranscriptEntry,
	status: Exclude<SandAutoReviewApprovalStatus, "pending">,
	requestId?: string,
): SandTranscriptEntry | null {
	if (
		entry.kind !== "send-message" ||
		entry.message.type !== "auto-review-approval" ||
		entry.message.approval.status !== "pending" ||
		(requestId != null && entry.message.approval.requestId !== requestId)
	) {
		return null;
	}
	return {
		...entry,
		message: {
			...entry.message,
			approval: {
				...entry.message.approval,
				status,
			},
		},
	};
}

export function settlePendingLocalToolPermissionEntry(
	entry: SandTranscriptEntry,
	status: Exclude<SandLocalToolPermissionStatus, "pending">,
	requestId?: string,
): SandTranscriptEntry | null {
	if (
		entry.kind !== "send-message" ||
		entry.message.type !== "local-tool-permission" ||
		entry.message.ask.status !== "pending" ||
		(requestId != null && entry.message.ask.requestId !== requestId)
	) {
		return null;
	}
	return {
		...entry,
		message: {
			...entry.message,
			ask: {
				...entry.message.ask,
				status,
			},
		},
	};
}

/**
 * Host-authored local-tool permission ask. Raised when the user's standing
 * permission is "ask" and the agent's turn wants the user's own computer. Like
 * the Auto-review card it is intentionally absent from the model-facing
 * SendMessage schema, so an assistant can neither manufacture a consent request
 * nor mark one granted. Pending asks dock above the composer; settled cards
 * remain in the transcript.
 */
export interface SandLocalToolPermissionAsk {
	readonly requestId: string;
	/** What this one action does on the machine, in the card's words. */
	readonly action: SandLocalToolAction;
	/** The concrete command or path the user is approving. */
	readonly target: string;
	readonly status: SandLocalToolPermissionStatus;
	/**
	 * Plain-English what the agent is about to do (display only). Prefer the
	 * model-authored shell description when present.
	 */
	readonly description?: string;
}

export interface SandEmailDraft {
	readonly from?: string;
	readonly to: readonly string[];
	readonly cc?: readonly string[];
	readonly subject: string;
	readonly body: string;
}

export interface SandSlackDraft {
	readonly workspace?: string;
	readonly target: string;
	readonly thread?: string;
	readonly body: string;
}

// One user-facing message the agent sends through SendMessage. The only channel
// that reaches the user; everything else (plain assistant text, tool calls) is
// internal. Shared by the brain (which produces it) and the host (which renders
// and persists it).
export type SandSendMessage =
	| {
			readonly type: "text";
			readonly content: string;
			// Optional images attached to this message, rendered inside the same
			// bubble below the text: one image full width, several as the shared
			// image-stack gallery. Absent means a plain text bubble, exactly as
			// before, so older hosts and persisted entries are unaffected.
			readonly images?: readonly SandSendMessageImage[];
			readonly reply_to?: string;
			readonly channel?: SandSendMessageChannel;
	  }
	| {
			// Files and standalone media use this shape. Historical transcripts may
			// also contain webpage URLs from before links became ordinary text with
			// renderer-owned unfurls, so the persisted union remains backward-compatible.
			readonly type: "attachment";
			readonly url: string;
			readonly reply_to?: string;
			// The original filename the attachment was sent with. The `url` points at a
			// content-addressed copy (`<sha256><ext>`), so this is what a non-image file
			// chip displays instead of the hash. Captured at ingest from the source
			// path's basename; absent for non-file urls and legacy entries.
			readonly file_name?: string;
			// Optional agent-authored description (alt text) of the image. When set,
			// the renderer shows it as a hover tooltip and as a fullscreen caption.
			readonly alt?: string;
			readonly channel?: SandSendMessageChannel;
			// Media pixel size measured at send time so the renderer frames the real
			// ratio before the bytes arrive. Absent for non-media/legacy entries.
			readonly width?: number;
			readonly height?: number;
	  }
	| {
			readonly type: "widget";
			readonly widget: SandWidget;
			readonly reply_to?: string;
	  }
	| {
			// References a Cursor cloud (background) agent by its bcId. Renders as a
			// card that, on click, opens the agent in the Cursor web app (cursor.com)
			// in the user's default browser.
			readonly type: "cursor-agent";
			readonly bcId: string;
			// The cloud agent's human-readable name, stamped at creation so the
			// sidebar/notification preview can show a meaningful title without a
			// per-render network fetch. Absent/empty falls back to a generic label.
			readonly title?: string;
			readonly reply_to?: string;
	  }
	| {
			// Requests a secret from the user through a masked secure input, never a
			// chat paste. Carries only the request metadata (label/description/target),
			// never a value; the submitted value is routed out of band by the host.
			readonly type: "secret-request";
			readonly secretRequest: SandSecretRequest;
			readonly reply_to?: string;
	  }
	| {
			readonly type: "email-draft";
			readonly draft: SandEmailDraft;
			readonly reply_to?: string;
	  }
	| {
			readonly type: "slack-draft";
			readonly draft: SandSlackDraft;
			readonly reply_to?: string;
	  }
	| {
			// DEPRECATED / legacy-only. The permission-request widget was unshipped.
			// This variant is retained solely so historical transcripts that persisted
			// such an entry still decode and render inertly; it is NOT in the
			// SendMessage schema, so the model can no longer create one. Do not add a
			// creation path.
			readonly type: "permission-request";
			readonly permission: SandPermissionRequest;
			readonly reply_to?: string;
	  }
	| {
			// Runtime-only. The host creates this card while Auto-review holds a
			// blocked action pending the user's decision. It cannot be emitted by
			// the SendMessage tool.
			readonly type: "auto-review-approval";
			readonly approval: SandAutoReviewApproval;
	  }
	| {
			// Runtime-only, like the Auto-review card above: the Host creates this
			// while a local tool (Shell / Read / AwaitShell / CopyToBox /
			// CopyFromBox) waits on the user's answer. The SendMessage tool
			// cannot emit it.
			readonly type: "local-tool-permission";
			readonly ask: SandLocalToolPermissionAsk;
	  }
	| {
			// An in-chat MCP connector card. The payload is intentionally minimal: the
			// renderer resolves the connector's live status, icon, and catalog entry
			// from the MCP manager by name, so a card never carries stale branding or
			// status. "connected" confirms an install/auth with a Manage action;
			// "connect" prompts the user to add it.
			readonly type: "connector";
			readonly connector: string;
			// The installed server row this card must represent. Several installed
			// rows can share a display name (e.g. a user and a team Notion), and a
			// name-resolved card degrades to a Manage deep-link on that ambiguity —
			// which dead-ends an agent-started per-account auth flow. When present,
			// the renderer resolves by this id and only falls back to the name.
			readonly serverId?: string;
			readonly variant: SandConnectorCardVariant;
			readonly reason?: string;
			// Optional, agent-chosen connectors to surface as one-tap discovery chips
			// under a "connect" card. The agent decides what (if anything) is relevant
			// to the task; absent means no discovery shelf. Each is resolved to a
			// catalog entry by name and dropped if unknown or already installed.
			readonly suggestions?: readonly string[];
			readonly reply_to?: string;
	  }
	| {
			// Prompts the user to connect SEVERAL MCP connectors at once — "to do
			// this, connect these tools". The agent chooses the list; the renderer
			// draws one connect card per connector (the same single-connector card,
			// stacked), so status, connect, and auth all share that one code path.
			readonly type: "connectors";
			readonly connectors: readonly string[];
			readonly reason?: string;
			readonly reply_to?: string;
	  }
	| {
			// An in-chat card to connect the user's Cursor account to Slack or GitHub
			// so LISTENER automations fire — distinct from the MCP `connector` card:
			// this is the account-level OAuth the backend relay reads (hasSlackAuth /
			// GitHub App install), not an MCP server. The payload is just the
			// platform; the renderer resolves live connection + relay status and its
			// Connect button opens the cursor.com authorization in the browser,
			// flipping to a connected confirmation in place once linked.
			readonly type: "listener-connect";
			readonly platform: SandListenerPlatform;
			readonly reason?: string;
			readonly reply_to?: string;
	  };

export type SandMessageRole = "user" | "assistant";

// Who sent a message, when it isn't simply "the agent of this conversation".
// Set on group-room messages so each member's reply is attributed to that
// member (avatar + name) instead of rendering as an anonymous assistant.
export interface SandMessageAuthor {
	readonly id: string;
	readonly name: string;
	// The kind of this identity, stamped at send time on an outbound peer target
	// (`toAgent`): an individual `"agent"` or a `"group"` room. It is the
	// AUTHORITATIVE, persisted target type the main-transcript row filter reads to
	// decide whether an outbound mirror renders — an individual `"agent"` target
	// draws a compact "To <agent>" chip, a `"group"` target stays hidden so group
	// routing can't spam the source chat. Absent on inbound (`fromAgent`) and
	// group-member (`author`) identities, and on legacy mirrors written before this
	// field existed; the filter treats a missing kind as non-individual (hidden),
	// so a legacy mirror fails toward the old safe no-spam default rather than
	// guessing groupness from a mutable roster at render time.
	readonly kind?: "agent" | "group";
}
// How a box handoff (request_box_help) ended, for the in-chat request card.
// "handed_back": user clicked "Hand back to agent". "replied": user answered in
// chat instead. "dismissed": the user declined the request without doing the
// step (the card's Dismiss action), or a newer request superseded it.
export type SandBoxHandoffResolution = "handed_back" | "replied" | "dismissed";

// The sentinel attributed to reactions the local user adds. Reactions are a
// list of {emoji, by} (not a count map) so a specific person's reaction can be
// toggled off; for this single-user desktop every user reaction is "me".
export const SAND_REACTION_SELF = "me";

// The sentinel for reactions the agent adds to a user's message (the rare
// tapback). Kept distinct from "me" so the renderer can attribute and style it
// as the agent's, and never let a click toggle it as if it were the user's.
export const SAND_REACTION_AGENT = "agent";

export interface SandReaction {
	readonly emoji: string;
	readonly by: string;
}

interface SandEntryBase {
	readonly id: string;
	readonly timestampMs?: number;
	readonly reactions?: readonly SandReaction[];
}

export interface SandMessageEntry extends SandEntryBase {
	readonly kind: "message";
	readonly role: SandMessageRole;
	readonly content: string;
	readonly richText?: string;
	readonly isStreaming: boolean;
	readonly replyTo?: string;
	// Set when this message belongs to a forked thread: a branched mini-conversation
	// scoped to a single source message. Forked entries are hidden from the main
	// transcript (collapsed behind a "thread" affordance on their fork root) and
	// only shown inside the thread overlay. Distinct from a plain reply, which
	// stays inline. Optional and backward-compatible (older entries omit it).
	readonly branched?: boolean;
	// A client-generated nonce echoed back from the renderer's send, letting the
	// desktop dedupe its optimistic bubble against this authoritative entry. An
	// older host omits it; the renderer then falls back to a content match.
	readonly clientNonce?: string;
	// The send's attachment batch (SandUserAttachmentEntry.batchId), so the
	// transcript draws the send's reply quote once, on the batch lead. Absent
	// for attachment-less sends and legacy entries.
	readonly batchId?: string;
	readonly sentWhileOfflineAtMs?: number;
	// Set when this message arrived from an outside platform (e.g. "slack:C123").
	// The renderer shows a platform tag on the bubble. Absent for in-app messages.
	readonly channel?: string;
	// The external sender's display name for an inbound channel message.
	readonly channelSender?: string;
	// Set when this message arrived from ANOTHER of the user's agents (an
	// agent-to-agent message). Carries only the sender's id and a fallback name;
	// the renderer resolves the live avatar/name from the roster by this id (so a
	// rename stays correct) and shows a "from <agent>" chip. Absent for ordinary
	// user and channel messages.
	readonly fromAgent?: SandMessageAuthor;
	// Set when this user-role message was posted by ANOTHER HUMAN in a shared
	// cross-user room — a guest texting a shared agent, or a remote member of a
	// cross-user group — never by the local user (whose messages stay
	// unattributed and render as "you"). Each box stamps this at materialize
	// time by comparing the wire author's authId against the signed-in user, so
	// the SAME room entry renders as "you" on the author's Sand and as a named
	// guest everywhere else. `avatarUrl` is the author's profile picture,
	// resolved server-side from their account at relay time (https-only) — the
	// renderer falls back to the identicon when absent. Optional and
	// backward-compatible.
	readonly fromUser?: {
		readonly name: string;
		readonly authId?: string;
		readonly avatarUrl?: string;
	};
	// The mirror of `fromAgent`: set when this agent SENT an agent-to-agent message
	// to another agent (or a group), recorded on the SENDER's own transcript as
	// internal routing bookkeeping. Recording both directions lets either agent's
	// transcript reconstruct the full two-way exchange by peer id (the exchange
	// overlay and the org chart), with no cross-transcript stitching. Whether it
	// ALSO renders in the sender's own chat depends on the target's persisted
	// `kind`: an individual `"agent"` target draws a compact "To <agent>" chip
	// (the counterpart of the inbound "From <peer>" chip), while a `"group"`
	// target — or a legacy mirror with no stamped kind — stays hidden, so group
	// coordination can't reintroduce routing-receipt spam in the source chat (see
	// isVisibleOutboundAgentPeerMessageEntry / isHiddenOutboundAgentPeerMessageEntry
	// and the renderer's shared row gate). Exactly one of `fromAgent` / `toAgent`
	// is ever set on a message.
	readonly toAgent?: SandMessageAuthor;
	// Image(s) attached to an agent-to-agent message (SendToAgent's images),
	// stamped on both the inbound (`fromAgent`) entry and the sender's outbound
	// (`toAgent`) mirror. The exchange "tunnel" renders them through the same
	// combined text+image bubble a SendMessage with images uses. Absent on every
	// other message kind.
	readonly images?: readonly SandSendMessageImage[];
}

export interface SandToolCallEntry extends SandEntryBase {
	readonly kind: "tool-call";
	readonly name: string;
	readonly status: SandToolCallStatus;
	readonly summary?: string;
}

export interface SandSendMessageEntry extends SandEntryBase {
	readonly kind: "send-message";
	readonly message: SandSendMessage;
	// Frozen thumbnail of the box desktop at the moment of a request_box_help
	// handoff, as a small data URL. Kept only in the in-memory transcript and
	// never persisted to store.db.
	readonly boxSnapshot?: string;
	// request_box_help metadata so the in-chat card is self-contained: the chat
	// message the agent sent, the short instruction shown on the box, a stable id
	// that matches the live handoff, and the terminal resolution once it ends.
	readonly boxRequest?: string;
	readonly boxInstruction?: string;
	readonly boxRequestId?: string;
	readonly boxResolution?: SandBoxHandoffResolution;
	readonly replyTo?: string;
	// Set when this message belongs to a forked thread (see SandMessageEntry).
	// Forked entries are hidden from the main transcript and shown only in the
	// thread overlay. Optional and backward-compatible.
	readonly branched?: boolean;
	// Set once the user resolves an interactive widget (e.g. picks a choice).
	// The renderer shows the stored value inline on the resolved card (see
	// getWidgetPresentation); the value also reaches the model as the next
	// turn's prompt, without a visible user message.
	readonly respondedValue?: string;
	// Legacy-only: set on entries answered during the short-lived echo-as-reply
	// era, whose pick was ALSO appended as a real user message right after the
	// widget. Those transcripts already carry the answer as a user bubble, so
	// the renderer collapses such an entry to the bare question instead of
	// repeating the pick inline. Never written anymore.
	readonly respondedValueEchoed?: boolean;
	// Set once the user explicitly dismisses a question widget without
	// answering (the card's Dismiss control). A dismissed widget is inert —
	// the host refuses late answers — and renders as the muted dismissed card.
	// Dismissal never wakes the agent; the model hears about it through the
	// unanswered-questions note on its next natural turn.
	readonly widgetDismissed?: boolean;
	// Set once the user submits a secret-request through the secure input. Only
	// this boolean is ever stored: the submitted value is routed out of band to
	// its target sink and never lands on the entry, the transcript, or the model.
	readonly secretProvided?: boolean;
	readonly draftSendState?: "sending" | "sent";
	// Set once the user moves past a question widget without answering it (they
	// sent a new message, answered a different widget, or the agent was revived by
	// background work). Keeps the "user skipped your question" note one-shot and
	// marks the widget as no longer awaiting a reply.
	readonly widgetSkipped?: boolean;
	// Identifies the run window an attachment message was sent in (the agent-side
	// mirror of SandUserAttachmentEntry.batchId), so consecutive attachments only
	// group into one "Sent N files" preview when they came from the same run —
	// two adjacent but separate sends never merge. Only stamped on attachment
	// messages; absent for other message types and legacy entries.
	readonly batchId?: string;
	// The group member who sent this message, when this is a group room. Absent
	// for ordinary single-agent conversations.
	readonly author?: SandMessageAuthor;
	// Set while a group member's reply is still streaming into the room live: the
	// bubble shows the member's accumulated text as it arrives, instead of the
	// room staying empty until the member's whole turn finishes. Opened only once
	// the member has VISIBLE text — a flagged entry with empty content renders no
	// row at all (see isEmptyStreamingPreviewEntry), so the group's live state
	// stays on the aggregated working indicator rather than a stray "…" bubble.
	// The entry is cache-only (never persisted) until it resolves into the final
	// committed message, at which point the flag is cleared. Absent everywhere
	// else (1:1 chats, committed group messages, older entries).
	readonly streaming?: boolean;
}

export interface SandUserAttachmentEntry extends SandEntryBase {
	readonly kind: "user-attachment";
	readonly file_path: string;
	// The original filename the user attached. The on-disk path is content-hashed,
	// so this is what a non-image file chip displays. Absent for legacy entries.
	readonly file_name?: string;
	// Identifies the batch of attachments sent together in one message, so the
	// transcript can render them as a single grouped block (images + files).
	// Absent for legacy entries.
	readonly batchId?: string;
	// The client nonce of the send this attachment belongs to, echoed back like
	// SandMessageEntry.clientNonce so an attachments-only send's ack resolves
	// exactly (by nonce, on any agent) instead of via the displayed-agent content
	// fallback. Absent for legacy entries / older hosts.
	readonly clientNonce?: string;
	readonly replyTo?: string;
	// Set when this attachment belongs to a forked thread (see SandMessageEntry).
	// Optional and backward-compatible.
	readonly branched?: boolean;
	readonly width?: number;
	readonly height?: number;
	readonly byteSize?: number;
}

export interface SandNoticeEntry extends SandEntryBase {
	readonly kind: "notice";
	readonly text: string;
	// Set when the notice was produced during a forked turn: it joins the fork's
	// hidden thread (via `replyTo` -> the branch point) instead of the main
	// transcript, matching the fork's messages. Absent for ordinary notices.
	readonly branched?: boolean;
	readonly replyTo?: string;
}

// A notable system/lifecycle happening in the conversation (a rename, a channel
// connecting, etc.). Carries the structured event so the renderer can draw a
// per-kind row and the agent's wake can describe it; see shared/timeline.ts.
export interface SandEventEntry extends SandEntryBase {
	readonly kind: "event";
	readonly event: SandTimelineEvent;
}

export type SandTranscriptEntry =
	| SandMessageEntry
	| SandSendMessageEntry
	| SandUserAttachmentEntry
	| SandToolCallEntry
	| SandNoticeEntry
	| SandEventEntry;

export type SandPendingLocalToolPermissionEntry = SandSendMessageEntry & {
	readonly message: {
		readonly type: "local-tool-permission";
		readonly ask: SandLocalToolPermissionAsk & { readonly status: "pending" };
	};
};

/** Pending local-tool asks dock above the composer; settled ones stay in-transcript as system-event lines. */
export function isPendingLocalToolPermissionEntry(
	entry: SandTranscriptEntry,
): entry is SandPendingLocalToolPermissionEntry {
	return (
		entry.kind === "send-message" &&
		entry.message.type === "local-tool-permission" &&
		entry.message.ask.status === "pending"
	);
}

export function isExpiredLocalToolPermissionEntry(entry: SandTranscriptEntry): boolean {
	return (
		entry.kind === "send-message" &&
		entry.message.type === "local-tool-permission" &&
		entry.message.ask.status === "expired"
	);
}

// The entry's reply/thread pointer, if any. Message, send-message, and
// user-attachment carry a user-visible reply quote; a notice carries one only to
// join a fork's hidden thread (it never renders a quote). Used for branch-root
// resolution, so all must be recognized here. Exported because the Chat
// feature's thread derivations resolve the same pointer.
export function getEntryReplyTo(entry: SandTranscriptEntry): string | undefined {
	if (
		entry.kind === "message" ||
		entry.kind === "send-message" ||
		entry.kind === "user-attachment" ||
		entry.kind === "notice"
	) {
		return entry.replyTo;
	}
	return undefined;
}

// True when an entry belongs to a thread — i.e. it was branched off a source
// message (mirrors the renderer's `isBranchedEntry` in `thread-view.ts`).
// Message-bearing entries plus fork-scoped notices can be branched.
function isBranchedEntry(entry: SandTranscriptEntry): boolean {
	if (
		entry.kind === "message" ||
		entry.kind === "send-message" ||
		entry.kind === "user-attachment" ||
		entry.kind === "notice"
	) {
		return entry.branched === true;
	}
	return false;
}

// The branch point a branched entry hangs off: the first non-branched ancestor
// PRESENT in the transcript, reached by climbing `replyTo` through branched
// ancestors. Mirrors `resolveBranchRoot` in the renderer's `thread-view.ts` so
// the sidebar preview and the main chat agree on exactly which entries are
// thread-only. Returns null when there is no resolvable, present branch point
// (missing parent, no present non-branched ancestor, or a cycle), so such an
// entry is treated as a main-chat message rather than silently hidden.
function resolveBranchRoot(
	entry: SandTranscriptEntry,
	byId: ReadonlyMap<string, SandTranscriptEntry>,
): string | null {
	let current = entry;
	const seen = new Set<string>([entry.id]);
	for (;;) {
		const parentId = getEntryReplyTo(current);
		if (parentId == null) return null;
		const parent = byId.get(parentId);
		if (parent == null) return null;
		if (!isBranchedEntry(parent)) return parentId;
		if (seen.has(parentId)) return null;
		seen.add(parentId);
		current = parent;
	}
}

// The entries the main transcript actually shows: standalone messages, plain
// replies, and thread roots, with every branched (thread) entry removed. A
// thread message is a branched entry that resolves to a present branch point;
// the main transcript collapses these behind a "N in thread" chip on their
// branch point and shows them only in the thread overlay. A plain reply (a
// `replyTo` with no `branched` flag) is a main-chat message and stays, as does a
// branched entry whose branch point is not loaded (so it never disappears). The
// renderer derives the identical visible set in `computeThreadView`, so the host
// reuses this to keep the sidebar last-message preview showing what is actually
// on screen in the main chat rather than a thread-only message. Returns the same
// reference when nothing is threaded so callers can skip work in the common case.
export function getMainTranscriptEntries(
	entries: readonly SandTranscriptEntry[],
): readonly SandTranscriptEntry[] {
	const byId = new Map<string, SandTranscriptEntry>(entries.map((entry) => [entry.id, entry]));
	const isThreadMessage = (entry: SandTranscriptEntry): boolean =>
		isBranchedEntry(entry) && resolveBranchRoot(entry, byId) != null;
	if (!entries.some(isThreadMessage)) return entries;
	return entries.filter((entry) => !isThreadMessage(entry));
}

// The thread pane rooted at `rootId`: the root plus the branched entries
// reachable from it without crossing a plain-reply boundary, in transcript
// order — the identical walk the renderer's open-thread pane performs
// (computeThreadDescendants in thread-graph.ts). Returns [] when the root is
// not present. Note a root with no branched replies yields just itself — "a
// thread exists under it" is a length > 1 check. Callers choose the root:
// the widget move-on guard deliberately roots at the widget ITSELF rather
// than resolving its branch point, because a renderer with a partial history
// window may not have the true root loaded and then roots its pane exactly
// there — the widget's own descendants are the one scope contained in every
// pane any client can render.
export function getThreadTranscriptEntries(
	entries: readonly SandTranscriptEntry[],
	rootId: string,
): readonly SandTranscriptEntry[] {
	const byId = new Map<string, SandTranscriptEntry>(entries.map((entry) => [entry.id, entry]));
	if (!byId.has(rootId)) return [];
	const childrenByParent = new Map<string, string[]>();
	for (const candidate of entries) {
		const parentId = getEntryReplyTo(candidate);
		if (parentId == null) continue;
		const bucket = childrenByParent.get(parentId);
		if (bucket == null) childrenByParent.set(parentId, [candidate.id]);
		else bucket.push(candidate.id);
	}
	// Walk down from the root, but only into branched children: a non-branched
	// child is a plain reply that belongs to the main transcript, and its
	// subtree is a different branch this thread must not absorb.
	const thread = new Set<string>([rootId]);
	const queue: string[] = [rootId];
	while (queue.length > 0) {
		const nextId = queue.shift();
		if (nextId == null) continue;
		for (const childId of childrenByParent.get(nextId) ?? []) {
			if (thread.has(childId)) continue;
			const child = byId.get(childId);
			if (child == null || !isBranchedEntry(child)) continue;
			thread.add(childId);
			queue.push(childId);
		}
	}
	return entries.filter((candidate) => thread.has(candidate.id));
}

// True when a message is an agent-to-agent (peer) exchange — an inbound message
// FROM another of the user's agents (`fromAgent`) or the sender's own mirror of
// a message it sent TO a peer (`toAgent`). Exactly one of the two is ever set.
// This is the single source of truth for "is this peer traffic", shared by the
// renderer (directional chip rendering) and the host (sidebar preview + unread
// silencing), so a new call site can never recognize only one direction.
export function isAgentPeerMessageEntry(entry: SandTranscriptEntry | undefined): boolean {
	return (
		entry != null && entry.kind === "message" && (entry.fromAgent != null || entry.toAgent != null)
	);
}

// The outbound direction: the sender's own persisted mirror of a message it sent
// TO a peer agent or group (`toAgent`), regardless of target kind. This is
// internal routing bookkeeping that lets the exchange overlay and the org chart
// reconstruct both directions from one transcript. Whether it also RENDERS in the
// sender's own chat is decided by the two kind-aware predicates below; this base
// guard just answers "is this the sender's outbound mirror" so callers can read
// `toAgent` off it.
export function isOutboundAgentPeerMessageEntry(
	entry: SandTranscriptEntry | undefined,
): entry is SandMessageEntry & { readonly toAgent: SandMessageAuthor } {
	return entry != null && entry.kind === "message" && entry.toAgent != null;
}

// The one outbound case that RENDERS in the sender's main 1:1 transcript: a
// mirror whose target is an individual agent (`toAgent.kind === "agent"`). It
// draws a compact "To <agent>" chip — the counterpart of the inbound
// "From <peer>" chip — so a user can see their agent hand work to another agent.
// Only an authoritative, send-time-stamped kind qualifies; groupness is never
// inferred from a mutable roster at render time.
export function isVisibleOutboundAgentPeerMessageEntry(
	entry: SandTranscriptEntry | undefined,
): entry is SandMessageEntry & { readonly toAgent: SandMessageAuthor } {
	return isOutboundAgentPeerMessageEntry(entry) && entry.toAgent.kind === "agent";
}

// The outbound mirror the main transcript still HIDES: a `"group"` target (group
// coordination must not spam the source chat with a "To <group>" receipt per
// send), OR a legacy mirror with no stamped kind, which fails toward that safe
// no-spam default. Both stay persisted (the exchange overlay / org chart
// reconstruct from them, and content search skips them since they are not
// revealable rows), but the shared row gate (getTranscriptRows) drops them
// structurally by this predicate so no receipt leaks into the source chat.
export function isHiddenOutboundAgentPeerMessageEntry(
	entry: SandTranscriptEntry | undefined,
): boolean {
	return isOutboundAgentPeerMessageEntry(entry) && entry.toAgent.kind !== "agent";
}

// Whether appending `entry` should raise the user's attention on the agent's
// sidebar row — bump the unread badge and the last-activity recency that floats
// the row. Agent-to-agent peer traffic (see `isAgentPeerMessageEntry`) stays in
// the chat but is SILENT: a user's agents delegating work to each other must not
// churn the sidebar like a stream of unread texts. This covers BOTH directions,
// including the now-visible "To <agent>" chip — seeing your agent hand off work
// is not an unread event. Every other entry (the user's own messages, channel
// inbound, the agent's user-facing SendMessage) counts.
export function entryRaisesUserActivitySignal(entry: SandTranscriptEntry): boolean {
	return !isAgentPeerMessageEntry(entry);
}
