import {
	AUDIO_MIME_FROM_EXTENSION,
	CLIENT_NATIVE_IMAGE_MIME_FROM_EXTENSION,
	EXTENSION_FROM_IMAGE_MIME,
	IMAGE_MIME_FROM_EXTENSION,
	VIDEO_MIME_FROM_EXTENSION,
	extensionOf,
} from "./media-extensions.js";

// Path→mime helpers over the shared media-extension data. The maps themselves
// live in `media-extensions.ts`, and the extension sniff is its node-free
// `extensionOf`, so the same resolution runs in every process.
export function imageMimeFromPath(filePath: string): string | undefined {
	return IMAGE_MIME_FROM_EXTENSION[extensionOf(filePath)];
}

// Mime for an image the host will SERVE as inline bytes: the desktop/vision
// decodable set plus formats only a native-decoding client (iOS/ImageIO for
// HEIC/HEIF) can render. `readImageAttachment` uses this so an iOS-sent HEIC
// round-trips as image bytes instead of resolving null (an empty placeholder),
// while `imageMimeFromPath` — desktop inline classification and vision gating —
// stays on the strictly Chromium/model-decodable set.
export function servableImageMimeFromPath(filePath: string): string | undefined {
	const ext = extensionOf(filePath);
	return IMAGE_MIME_FROM_EXTENSION[ext] ?? CLIENT_NATIVE_IMAGE_MIME_FROM_EXTENSION[ext];
}

export function extensionFromImageMime(mime: string): string | undefined {
	return EXTENSION_FROM_IMAGE_MIME[mime.toLowerCase()];
}

export function videoMimeFromPath(filePath: string): string | undefined {
	return VIDEO_MIME_FROM_EXTENSION[extensionOf(filePath)];
}

export function audioMimeFromPath(filePath: string): string | undefined {
	return AUDIO_MIME_FROM_EXTENSION[extensionOf(filePath)];
}
