/**
 * Wire-stable attachment kinds. Mobile decoders map unknown newer values
 * to `file`.
 */

// The semantic attachment kinds carried on the wire (SandAgentLastEntry's
// typed counts). Wire-stable strings: mobile decodes them by name and degrades
// unknown values from a newer host to "file" instead of failing the decode.
export const SAND_ATTACHMENT_KINDS = [
	"image",
	"video",
	"audio",
	"pdf",
	"markdown",
	"table",
	"json",
	"text",
	"document",
	"archive",
	"file",
] as const;

export type SandAttachmentKind = (typeof SAND_ATTACHMENT_KINDS)[number];

// One kind's tally inside a batch summary, in first-seen (send) order.
export interface SandAttachmentKindCount {
	readonly kind: SandAttachmentKind;
	readonly count: number;
}

const KIND_LABELS: Record<
	SandAttachmentKind,
	{ readonly singular: string; readonly plural: string }
> = {
	image: { singular: "image", plural: "images" },
	video: { singular: "video", plural: "videos" },
	audio: { singular: "audio file", plural: "audio files" },
	pdf: { singular: "PDF", plural: "PDFs" },
	markdown: { singular: "Markdown file", plural: "Markdown files" },
	table: { singular: "spreadsheet", plural: "spreadsheets" },
	json: { singular: "JSON file", plural: "JSON files" },
	text: { singular: "text file", plural: "text files" },
	document: { singular: "document", plural: "documents" },
	archive: { singular: "archive", plural: "archives" },
	file: { singular: "file", plural: "files" },
};

function kindPhrase(kind: SandAttachmentKind, count: number): string {
	const label = KIND_LABELS[kind];
	return `${count} ${count === 1 ? label.singular : label.plural}`;
}

function mergeKindCounts(
	kinds: readonly SandAttachmentKindCount[] | undefined,
): readonly SandAttachmentKindCount[] {
	if (kinds == null || kinds.length === 0) return [];
	const known = kinds
		.filter((entry) => entry.count > 0)
		.map((entry) =>
			KIND_LABELS[entry.kind] != null ? entry : { kind: "file" as const, count: entry.count },
		);
	const merged = new Map<SandAttachmentKind, number>();
	for (const entry of known) {
		merged.set(entry.kind, (merged.get(entry.kind) ?? 0) + entry.count);
	}
	return [...merged].map(([kind, count]) => ({ kind, count }));
}

/**
 * Formats a typed attachment batch. Missing counts from older Hosts degrade to
 * a generic file total.
 */
export function formatAttachmentSentSummary(
	count: number,
	kinds?: readonly SandAttachmentKindCount[],
): string {
	const total = Math.max(1, Math.floor(count));
	const merged = mergeKindCounts(kinds);
	if (merged.length === 0) return `Sent ${kindPhrase("file", total)}`;
	const first = merged[0];
	if (merged.length === 1 && first != null) {
		return `Sent ${kindPhrase(first.kind, total)}`;
	}
	const breakdown = merged.map((entry) => kindPhrase(entry.kind, entry.count)).join(", ");
	return `Sent ${kindPhrase("file", total)} · ${breakdown}`;
}

export interface SandLinkMetadata {
	readonly url: string;
	readonly canonicalUrl: string;
	readonly title: string;
	readonly description: string;
	readonly siteName: string;
	readonly hostname: string;
	readonly imageDataUrl: string | null;
	readonly faviconDataUrl: string | null;
	readonly fetchedAt: number;
}

/** Desktop-to-Host attachment upload arguments. */

// A chat attachment uploaded into the host's agent data dir. The desktop sends
// the raw bytes (base64); the host content-addresses them under the agent's
// `attachments` dir and returns the host-side path the send-prompt path then
// carries (instead of a desktop-local path an in-box host can't read).
export interface SandUploadAttachmentArgs {
	// The agent the attachment is staged for. Omitted falls back to the host's
	// active agent (the composer always stages for the open conversation).
	readonly agentId?: string;
	readonly filename: string;
	readonly bytesBase64: string;
}

export interface SandUploadAttachmentResult {
	readonly path: string;
}

// Read a text attachment the host owns as a capped UTF-8 preview, for the in-box
// file card (the desktop can't read the box's disk). `agentId` scopes the read
// to that agent's `attachments` dir host-side; omitted falls back to the host's
// active agent.
export interface SandReadAttachmentTextArgs {
	readonly agentId?: string;
	readonly path: string;
}

// Read a byte slice of a host-owned attachment/asset, for the in-box video
// stream + file download paths. `offset`/`length` bound the slice (length 0 is a
// metadata probe returning totalSize+mime with no bytes); the host clamps both
// and caps a single response so a huge file never rides one RPC. `agentId`
// scopes the read to that agent's `attachments`/`assets` dirs host-side; omitted
// falls back to the host's active agent.
export interface SandReadAttachmentChunkArgs {
	readonly agentId?: string;
	readonly path: string;
	readonly offset: number;
	readonly length: number;
	readonly videoPlayback?: boolean;
}

// A byte slice of a host-owned attachment/asset, for the in-box desktop's video
// streaming + file-download paths (the desktop can't read the box's disk, so it
// pulls bytes over the gateway). A `length` of 0 is a metadata probe: it returns
// `totalSize` + `mime` with no bytes, so the caller can compute an HTTP range
// before fetching. A single read is capped (ATTACHMENT_CHUNK_MAX_BYTES) so a
// large file is pulled in bounded slices rather than one giant RPC.
export interface SandAttachmentChunk {
	readonly bytesBase64: string;
	readonly totalSize: number;
	// image/video/audio content-type for the media protocol to label its streamed
	// response; null for other (downloadable) types, which don't need one.
	readonly mime: string | null;
}

export interface ResolvedImageAttachment {
	readonly dataUrl: string;
	readonly width: number | null;
	readonly height: number | null;
}

export interface ResolvedVideoAttachment {
	readonly src: string;
	readonly width: number | null;
	readonly height: number | null;
}

export interface ResolvedAudioAttachment {
	readonly src: string;
}

export type ResolvedAttachmentMedia =
	| ({ readonly kind: "image" } & ResolvedImageAttachment)
	| ({ readonly kind: "video" } & ResolvedVideoAttachment)
	| ({ readonly kind: "audio" } & ResolvedAudioAttachment);

export type ResolvedAttachmentBytes =
	| { readonly kind: "bytes"; readonly bytes: Uint8Array }
	| { readonly kind: "too-large"; readonly size: number };

export type StageAttachmentFailureReason = "too-large" | "empty" | "failed";

export type StageAttachmentResult =
	| { readonly ok: true; readonly path: string }
	| { readonly ok: false; readonly reason: StageAttachmentFailureReason };

export interface SandPickedAvatarFile {
	readonly dataUrl: string;
	readonly fileName: string;
}

// The result of resolving an attachment for the file-reference card. A
// text-previewable file (by extension AND byte sniff) comes back as "text" with
// a capped UTF-8 body; anything binary (a .zip and other archives, executables,
// office docs, or a text-named file whose bytes sniff binary) comes back as
// "binary" with just its size, so the card renders a clean download-only chip
// instead of mojibake. `null` (handled by callers) still means "couldn't read".
export type ResolvedTextAttachment =
	| {
			readonly kind: "text";
			readonly text: string;
			readonly truncated: boolean;
			readonly bytes: number;
	  }
	| {
			readonly kind: "binary";
			readonly bytes: number;
	  };
