import { existsSync, statSync } from "node:fs";
import { resolve } from "node:path";
import { DatabaseSync } from "node:sqlite";

// How long a write waits out a conflicting lock before SQLite gives up. Sand's
// agent dbs are only ever contended across host processes (node:sqlite is
// synchronous, so one process can't deadlock itself), and the host single-
// instance lock keeps that window to a brief host hand-off — so a few seconds is
// plenty. Kept moderate because busy_timeout blocks the thread synchronously;
// too long would freeze the host's gateway.
export const DB_BUSY_TIMEOUT_MS = 5_000;

const dbWriteGenerations = new Map<string, number>();

export function getSandAgentDbWriteGeneration(dbPath: string): number {
	return dbWriteGenerations.get(resolve(dbPath)) ?? 0;
}

export function bumpDbWriteGeneration(resolvedDbPath: string): void {
	dbWriteGenerations.set(resolvedDbPath, (dbWriteGenerations.get(resolvedDbPath) ?? 0) + 1);
}

export function deleteSandAgentDbWriteGeneration(dbPath: string): void {
	dbWriteGenerations.delete(resolve(dbPath));
}

const liveDbHandlesByPath = new Map<string, number>();

export function liveDbHandleCount(resolvedDbPath: string): number {
	return liveDbHandlesByPath.get(resolvedDbPath) ?? 0;
}

export function registerLiveDbHandle(resolvedDbPath: string): void {
	liveDbHandlesByPath.set(resolvedDbPath, liveDbHandleCount(resolvedDbPath) + 1);
}

export function releaseLiveDbHandle(resolvedDbPath: string): void {
	const next = liveDbHandleCount(resolvedDbPath) - 1;
	if (next <= 0) liveDbHandlesByPath.delete(resolvedDbPath);
	else liveDbHandlesByPath.set(resolvedDbPath, next);
}

export function hasLiveSandAgentDbHandle(dbPath: string): boolean {
	return liveDbHandleCount(resolve(dbPath)) > 0;
}

// Folds any committed-but-uncheckpointed WAL frames back into the main store.db
// file. With WAL, a live writer can leave recent commits sitting in the `-wal`
// sidecar, so a raw byte copy of store.db alone (as export does) would snapshot
// a stale file and silently drop the newest messages. Run this against the
// source before copying.
//
// Interpret a `PRAGMA wal_checkpoint(TRUNCATE)` result row: were ALL of the WAL's
// frames FOLDED into the main file (so a byte-copy of the main file is CURRENT),
// regardless of whether the -wal was truncated? SQLite reports `{busy, log,
// checkpointed}`:
//   - `checkpointed >= log` with NON-NEGATIVE counts ⇒ true. This includes the
//     folded-but-untruncated case `{busy:1, log:N, checkpointed:N}` (a live reader
//     blocked TRUNCATE but every frame reached the main file — durable).
//   - `checkpointed < log` (non-negative) ⇒ false: only some frames folded (a reader
//     pinned an OLDER snapshot), so the main file is behind — NOT durable.
//   - The FULLY-BLOCKED sentinel `{busy:1, log:-1, checkpointed:-1}` ⇒ `undefined`.
//     When TRUNCATE cannot acquire the exclusive CHECKPOINTER lock (e.g. a concurrent
//     auto-checkpoint from another connection on a busy box), SQLite returns this
//     WITHOUT throwing — and `busy_timeout` does NOT apply to that lock — having
//     folded ZERO frames. `checkpointed >= log` would misread `-1 >= -1` as "folded"
//     and let a caller byte-copy a STALE main file (committed frames LOST on a roll):
//     the data-loss trap. So negative counts are reported as UNKNOWN and the caller
//     must fall back to a fail-closed signal (the -wal-empty check).
//   - Missing / non-numeric counts (an unexpected row shape) ⇒ `undefined` (same
//     fallback).
// Pure so the exact durable-vs-stale boundary is unit-tested (the counts can't be
// forced from real SQLite synchronously).
export function walFramesFullyFolded(
	row: { readonly log?: unknown; readonly checkpointed?: unknown } | undefined,
): boolean | undefined {
	const log = typeof row?.log === "number" ? row.log : undefined;
	const checkpointed = typeof row?.checkpointed === "number" ? row.checkpointed : undefined;
	if (log === undefined || checkpointed === undefined) return undefined;
	if (log < 0 || checkpointed < 0) return undefined;
	return checkpointed >= log;
}

export function checkpointSandAgentDb(
	dbPath: string,
	busyTimeoutMs: number = DB_BUSY_TIMEOUT_MS,
): boolean {
	if (!existsSync(dbPath)) return true;
	let db: DatabaseSync | undefined;
	let result: { readonly log?: unknown; readonly checkpointed?: unknown } | undefined;
	try {
		db = new DatabaseSync(dbPath);
		db.exec(`PRAGMA busy_timeout = ${busyTimeoutMs}`);
		result = db.prepare("PRAGMA wal_checkpoint(TRUNCATE)").get() as typeof result;
	} catch {
		return false;
	} finally {
		db?.close();
	}
	const folded = walFramesFullyFolded(result);
	if (folded !== undefined) {
		return folded;
	}
	try {
		return statSync(`${dbPath}-wal`).size === 0;
	} catch (error) {
		return (error as NodeJS.ErrnoException)?.code === "ENOENT";
	}
}

// The sidecar files a live SQLite db can pair with: the WAL + its shared-memory
// index, and the rollback journal. A raw byte copy must grab these alongside the
// main file so SQLite can recover the copy to a consistent state when it is opened
// (roll back a hot journal, replay/checkpoint a WAL).
export const SQLITE_DB_SIDECAR_SUFFIXES = ["-wal", "-shm", "-journal"] as const;
