import { basename, extname } from "node:path";
import { DatabaseSync } from "node:sqlite";

import { classifyAttachment } from "../../../shared/media/attachment-summary.js";
import {
	SAND_ATTACHMENT_KINDS,
	type SandAttachmentKind,
} from "../../../shared/media/attachments.js";
import {
	audioMimeFromPath,
	imageMimeFromPath,
	videoMimeFromPath,
} from "../../../shared/media/image-mime.js";
import type { SandMediaMatch, SandMessageMatch } from "../../../shared/search.js";
import {
	isHiddenOutboundAgentPeerMessageEntry,
	type SandTranscriptEntry,
} from "../../../shared/transcript.js";
import { DB_BUSY_TIMEOUT_MS } from "../../storage/store-db.js";
import {
	AGENT_CONTENT_SEARCH_MAX_MATCHES_PER_AGENT,
	entrySearchText,
} from "./agent-content-search.js";

export const SEARCH_INDEX_SCHEMA_VERSION = 1;

export const SEARCH_INDEX_FILENAME = "search-index.db";

const INDEXED_BODY_MAX_CHARS = 20_000;

const FTS_QUERY_MAX_TERMS = 8;

const SNIPPET_CONTEXT_TOKENS = 16;

const META_RECONCILE_DONE = "reconcile_done";

const ATTACHMENT_KINDS: ReadonlySet<string> = new Set(SAND_ATTACHMENT_KINDS);

// Folds a persisted kind this build doesn't know (an index written by a newer
// host) into the generic "file", mirroring how the wire degrades unknown
// attachment kinds.
function parseAttachmentKind(kind: string): SandAttachmentKind {
	return ATTACHMENT_KINDS.has(kind) ? (kind as SandAttachmentKind) : "file";
}

const SCHEMA = `
CREATE TABLE IF NOT EXISTS meta (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL
) STRICT;
CREATE TABLE IF NOT EXISTS agents (
  agent_id TEXT PRIMARY KEY,
  fingerprint TEXT NOT NULL
) STRICT;
CREATE TABLE IF NOT EXISTS messages (
  id INTEGER PRIMARY KEY,
  agent_id TEXT NOT NULL,
  entry_id TEXT NOT NULL,
  role TEXT NOT NULL CHECK (role IN ('user', 'assistant')),
  timestamp_ms INTEGER NOT NULL,
  body TEXT NOT NULL,
  UNIQUE(agent_id, entry_id)
) STRICT;
CREATE INDEX IF NOT EXISTS messages_agent_recency
  ON messages(agent_id, timestamp_ms DESC);
CREATE VIRTUAL TABLE IF NOT EXISTS messages_fts USING fts5(
  body,
  content='messages',
  content_rowid='id',
  tokenize='unicode61 remove_diacritics 2',
  prefix='2 3'
);
CREATE TRIGGER IF NOT EXISTS messages_fts_insert AFTER INSERT ON messages BEGIN
  INSERT INTO messages_fts(rowid, body) VALUES (new.id, new.body);
END;
CREATE TRIGGER IF NOT EXISTS messages_fts_delete AFTER DELETE ON messages BEGIN
  INSERT INTO messages_fts(messages_fts, rowid, body)
    VALUES ('delete', old.id, old.body);
END;
CREATE TRIGGER IF NOT EXISTS messages_fts_update AFTER UPDATE ON messages BEGIN
  INSERT INTO messages_fts(messages_fts, rowid, body)
    VALUES ('delete', old.id, old.body);
  INSERT INTO messages_fts(rowid, body) VALUES (new.id, new.body);
END;
CREATE TABLE IF NOT EXISTS media (
  id INTEGER PRIMARY KEY,
  agent_id TEXT NOT NULL,
  entry_id TEXT NOT NULL,
  file_name TEXT NOT NULL,
  ext TEXT NOT NULL,
  mime TEXT,
  kind TEXT NOT NULL,
  timestamp_ms INTEGER NOT NULL,
  width INTEGER,
  height INTEGER,
  UNIQUE(agent_id, entry_id)
) STRICT;
CREATE INDEX IF NOT EXISTS media_recency ON media(timestamp_ms DESC);
CREATE VIRTUAL TABLE IF NOT EXISTS media_fts USING fts5(
  file_name,
  content='media',
  content_rowid='id',
  tokenize='unicode61 remove_diacritics 2',
  prefix='2 3'
);
CREATE TRIGGER IF NOT EXISTS media_fts_insert AFTER INSERT ON media BEGIN
  INSERT INTO media_fts(rowid, file_name) VALUES (new.id, new.file_name);
END;
CREATE TRIGGER IF NOT EXISTS media_fts_delete AFTER DELETE ON media BEGIN
  INSERT INTO media_fts(media_fts, rowid, file_name)
    VALUES ('delete', old.id, old.file_name);
END;
CREATE TRIGGER IF NOT EXISTS media_fts_update AFTER UPDATE ON media BEGIN
  INSERT INTO media_fts(media_fts, rowid, file_name)
    VALUES ('delete', old.id, old.file_name);
  INSERT INTO media_fts(rowid, file_name) VALUES (new.id, new.file_name);
END;
`;

// Whether this runtime's node:sqlite was compiled with FTS5. The shipped Sand
// runtimes (the in-box host's node, Electron-as-node on a laptop) have it; an
// older dev node may not, in which case the service stays unavailable and
// content search degrades to the legacy linear scan.
export function isFts5Available(): boolean {
	let db: DatabaseSync | undefined;
	try {
		db = new DatabaseSync(":memory:");
		db.exec("CREATE VIRTUAL TABLE fts5_probe USING fts5(x)");
		return true;
	} catch {
		return false;
	} finally {
		db?.close();
	}
}

// Opens the index db with the same concurrency posture as the agent stores:
// WAL so the host's read (query) connection never blocks on the worker's
// writes, NORMAL sync (the index is fully re-derivable, so durability of the
// last few commits is irrelevant), and incremental auto-vacuum so bulk deletes
// (agent removal, reindex) return pages without a full VACUUM. auto_vacuum is
// set before the first table so it takes effect on a fresh file — the only
// kind this module ever creates, since rebuilds delete the file outright.
export function openSearchIndexDb(dbPath: string): DatabaseSync {
	const db = new DatabaseSync(dbPath);
	try {
		db.exec(`PRAGMA busy_timeout = ${DB_BUSY_TIMEOUT_MS}`);
		db.exec("PRAGMA journal_mode = WAL");
		db.exec("PRAGMA synchronous = NORMAL");
		db.exec("PRAGMA auto_vacuum = INCREMENTAL");
		return db;
	} catch (error) {
		try {
			db.close();
		} catch {}
		throw error;
	}
}

export function ensureSearchIndexSchema(db: DatabaseSync): void {
	db.exec(SCHEMA);
}

export function readSearchIndexSchemaVersion(db: DatabaseSync): number {
	const row = db.prepare("PRAGMA user_version").get() as
		| { readonly user_version?: number | bigint }
		| undefined;
	return typeof row?.user_version === "number" ? row.user_version : 0;
}

export function stampSearchIndexSchemaVersion(db: DatabaseSync): void {
	db.exec(`PRAGMA user_version = ${SEARCH_INDEX_SCHEMA_VERSION}`);
}

export function readReconcileDone(db: DatabaseSync): boolean {
	const row = db.prepare("SELECT value FROM meta WHERE key = ?").get(META_RECONCILE_DONE);
	return row?.value === "1";
}

export function writeReconcileDone(db: DatabaseSync): void {
	db.prepare(
		"INSERT INTO meta (key, value) VALUES (?, '1') ON CONFLICT(key) DO UPDATE SET value = '1'",
	).run(META_RECONCILE_DONE);
}

export interface SearchIndexMessageRow {
	readonly entryId: string;
	readonly role: "user" | "assistant";
	readonly timestampMs: number;
	readonly body: string;
}

export function deriveMessageRow(entry: SandTranscriptEntry): SearchIndexMessageRow | null {
	if (isHiddenOutboundAgentPeerMessageEntry(entry)) return null;
	const body = entrySearchText(entry).trim();
	if (body.length === 0) return null;
	return {
		entryId: entry.id,
		role: entry.kind === "message" ? entry.role : "assistant",
		timestampMs: wholeMs(entry.timestampMs),
		body: body.slice(0, INDEXED_BODY_MAX_CHARS),
	};
}

function wholeMs(value: number | undefined): number {
	return typeof value === "number" && Number.isFinite(value) ? Math.round(value) : 0;
}

function wholeDimension(value: number | undefined): number | null {
	return typeof value === "number" && Number.isFinite(value) ? Math.round(value) : null;
}

export interface SearchIndexMediaRow {
	readonly entryId: string;
	readonly fileName: string;
	readonly ext: string;
	readonly mime: string | null;
	readonly kind: string;
	readonly timestampMs: number;
	readonly width: number | null;
	readonly height: number | null;
}

function mediaFileName(fileName: string | undefined, urlOrPath: string): string {
	const trimmed = fileName?.trim();
	if (trimmed != null && trimmed.length > 0) return trimmed;
	let subject = urlOrPath;
	try {
		subject = new URL(urlOrPath).pathname;
	} catch {}
	try {
		subject = decodeURIComponent(subject);
	} catch {}
	return basename(subject);
}

export function deriveMediaRow(entry: SandTranscriptEntry): SearchIndexMediaRow | null {
	let fileName: string;
	let urlOrPath: string;
	let width: number | null = null;
	let height: number | null = null;
	if (entry.kind === "user-attachment") {
		urlOrPath = entry.file_path;
		fileName = mediaFileName(entry.file_name, urlOrPath);
		width = wholeDimension(entry.width);
		height = wholeDimension(entry.height);
	} else if (entry.kind === "send-message" && entry.message.type === "attachment") {
		urlOrPath = entry.message.url;
		fileName = mediaFileName(entry.message.file_name, urlOrPath);
	} else {
		return null;
	}
	if (fileName.length === 0) return null;
	const ext = extname(fileName).toLowerCase();
	const mime =
		imageMimeFromPath(fileName) ??
		videoMimeFromPath(fileName) ??
		audioMimeFromPath(fileName) ??
		null;
	return {
		entryId: entry.id,
		fileName,
		ext,
		mime,
		kind: classifyAttachment({ fileName, urlOrPath }),
		timestampMs: wholeMs(entry.timestampMs),
		width,
		height,
	};
}

// Builds an injection-safe FTS5 MATCH expression from raw user input: each
// whitespace-separated term becomes a quoted (double-quote-escaped) prefix
// query, joined by FTS5's implicit AND. Quoting means user input can never be
// parsed as FTS5 syntax (NEAR, OR, column filters, parens). Returns null when
// the query holds no searchable term.
export function buildFtsMatchQuery(query: string): string | null {
	const terms = query
		.normalize("NFKC")
		.trim()
		.split(/\s+/)
		.filter((term) => term.length > 0)
		.slice(0, FTS_QUERY_MAX_TERMS);
	if (terms.length === 0) return null;
	return terms.map((term) => `"${term.replaceAll('"', '""')}"*`).join(" ");
}

function flattenSnippet(text: string): string {
	return text.replace(/\s+/g, " ").trim();
}

export function searchMessages(db: DatabaseSync, query: string, limit: number): SandMessageMatch[] {
	const match = buildFtsMatchQuery(query);
	if (match == null || limit <= 0) return [];
	const effectiveTimestamp = `CASE
		WHEN m.timestamp_ms > 0 THEN m.timestamp_ms
		ELSE COALESCE(
			(SELECT MAX(m2.timestamp_ms) FROM messages m2 WHERE m2.agent_id = m.agent_id),
			0
		)
	END`;
	const rows = db
		.prepare(
			`SELECT
				m.agent_id AS agentId,
				m.entry_id AS entryId,
				m.role AS role,
				matched.ts AS timestampMs,
				snippet(messages_fts, 0, '', '', '…', ${SNIPPET_CONTEXT_TOKENS}) AS snippet
			 FROM (
				SELECT fts_rowid, ts FROM (
					SELECT
						fts_rowid,
						ts,
						ROW_NUMBER() OVER (
							PARTITION BY agent_id
							ORDER BY ts DESC
						) AS agent_rank
					FROM (
						SELECT
							messages_fts.rowid AS fts_rowid,
							m.agent_id AS agent_id,
							${effectiveTimestamp} AS ts
						FROM messages_fts
						JOIN messages m ON m.id = messages_fts.rowid
						WHERE messages_fts MATCH ?
					)
				)
				WHERE agent_rank <= ${AGENT_CONTENT_SEARCH_MAX_MATCHES_PER_AGENT}
				ORDER BY ts DESC
				LIMIT ?
			 ) AS matched
			 JOIN messages_fts ON messages_fts.rowid = matched.fts_rowid
			 JOIN messages m ON m.id = matched.fts_rowid
			 WHERE messages_fts MATCH ?
			 ORDER BY matched.ts DESC`,
		)
		.all(match, limit, match);
	const results: SandMessageMatch[] = [];
	for (const row of rows) {
		if (
			typeof row.agentId !== "string" ||
			typeof row.entryId !== "string" ||
			(row.role !== "user" && row.role !== "assistant") ||
			typeof row.timestampMs !== "number" ||
			typeof row.snippet !== "string"
		) {
			continue;
		}
		results.push({
			agentId: row.agentId,
			entryId: row.entryId,
			role: row.role,
			timestampMs: row.timestampMs,
			snippet: flattenSnippet(row.snippet),
		});
	}
	return results;
}

export function searchMedia(db: DatabaseSync, query: string, limit: number): SandMediaMatch[] {
	if (limit <= 0) return [];
	const match = buildFtsMatchQuery(query);
	const selectColumns = `
		md.agent_id AS agentId,
		md.entry_id AS entryId,
		md.file_name AS fileName,
		md.ext AS ext,
		md.mime AS mime,
		md.kind AS kind,
		md.timestamp_ms AS timestampMs,
		md.width AS width,
		md.height AS height`;
	const rows =
		match == null
			? db
					.prepare(
						`SELECT ${selectColumns}
						 FROM media md
						 ORDER BY md.timestamp_ms DESC
						 LIMIT ?`,
					)
					.all(limit)
			: db
					.prepare(
						`SELECT ${selectColumns}
						 FROM media_fts
						 JOIN media md ON md.id = media_fts.rowid
						 WHERE media_fts MATCH ?
						 ORDER BY md.timestamp_ms DESC
						 LIMIT ?`,
					)
					.all(match, limit);
	const results: SandMediaMatch[] = [];
	for (const row of rows) {
		if (
			typeof row.agentId !== "string" ||
			typeof row.entryId !== "string" ||
			typeof row.fileName !== "string" ||
			typeof row.ext !== "string" ||
			typeof row.kind !== "string" ||
			typeof row.timestampMs !== "number"
		) {
			continue;
		}
		results.push({
			agentId: row.agentId,
			entryId: row.entryId,
			fileName: row.fileName,
			ext: row.ext,
			mime: typeof row.mime === "string" ? row.mime : null,
			kind: parseAttachmentKind(row.kind),
			timestampMs: row.timestampMs,
			width: typeof row.width === "number" ? row.width : null,
			height: typeof row.height === "number" ? row.height : null,
		});
	}
	return results;
}
