import { attachmentExtension } from "./attachment-open-policy.js";
import { isTextPreviewableName } from "./attachment-preview.js";
import {
	AUDIO_MIME_FROM_EXTENSION,
	IMAGE_MIME_FROM_EXTENSION,
	VIDEO_MIME_FROM_EXTENSION,
} from "./media-extensions.js";

export type FilePreviewKind =
	| "image"
	| "video"
	| "audio"
	| "pdf"
	| "markdown"
	| "text"
	| "json"
	| "table"
	| "docx"
	| "unknown";

const IMAGE_EXTENSIONS: ReadonlySet<string> = new Set(
	Object.keys(IMAGE_MIME_FROM_EXTENSION).map((ext) => ext.slice(1)),
);
const VIDEO_EXTENSIONS: ReadonlySet<string> = new Set(
	Object.keys(VIDEO_MIME_FROM_EXTENSION).map((ext) => ext.slice(1)),
);
const AUDIO_EXTENSIONS: ReadonlySet<string> = new Set(
	Object.keys(AUDIO_MIME_FROM_EXTENSION).map((ext) => ext.slice(1)),
);

const MARKDOWN_EXTENSIONS: ReadonlySet<string> = new Set(["md", "markdown", "mdx"]);

const JSON_EXTENSIONS: ReadonlySet<string> = new Set(["json"]);

const TABLE_EXTENSIONS: ReadonlySet<string> = new Set(["csv", "tsv", "xlsx", "xls"]);

const DELIMITED_TEXT_TABLE_EXTENSIONS: ReadonlySet<string> = new Set(["csv", "tsv"]);

export function getFilePreviewKind(nameOrPath: string): FilePreviewKind {
	const ext = attachmentExtension(nameOrPath);
	if (ext == null) return "unknown";
	if (IMAGE_EXTENSIONS.has(ext)) return "image";
	if (VIDEO_EXTENSIONS.has(ext)) return "video";
	if (AUDIO_EXTENSIONS.has(ext)) return "audio";
	if (ext === "pdf") return "pdf";
	if (TABLE_EXTENSIONS.has(ext)) return "table";
	if (JSON_EXTENSIONS.has(ext)) return "json";
	if (MARKDOWN_EXTENSIONS.has(ext)) return "markdown";
	if (ext === "docx") return "docx";
	if (isTextPreviewableName(nameOrPath)) return "text";
	return "unknown";
}

// `.csv`/`.tsv`: decode UTF-8 and parse rows instead of loading a workbook.
export function isDelimitedTextTable(nameOrPath: string): boolean {
	const ext = attachmentExtension(nameOrPath);
	return ext != null && DELIMITED_TEXT_TABLE_EXTENSIONS.has(ext);
}

// Only the hint the parser starts from; it still autodetects per file.
export function delimitedTableSeparator(nameOrPath: string): "," | "\t" {
	return attachmentExtension(nameOrPath) === "tsv" ? "\t" : ",";
}

// Kinds whose fullscreen reader needs the file's raw bytes rather than the
// capped inline text the file card already reads; drives whether the byte
// reader will serve the file.
export function previewKindNeedsBytes(kind: FilePreviewKind): boolean {
	return (
		kind === "pdf" ||
		kind === "table" ||
		kind === "docx" ||
		kind === "text" ||
		kind === "json" ||
		kind === "markdown"
	);
}

export function isFullscreenFileKind(kind: FilePreviewKind): boolean {
	return kind !== "unknown";
}
