import { attachmentExtension } from "./attachment-open-policy.js";
import type { SandAttachmentKind, SandAttachmentKindCount } from "./attachments.js";
import { getFilePreviewKind } from "./file-preview-kind.js";

// Every field optional so the classifier serves all producers (name + path,
// name + url, or a staged browser file's MIME type). `fileName` admits an
// explicit undefined: the reply preview passes a possibly-absent original
// name under exactOptionalPropertyTypes.
export interface SandAttachmentSource {
	readonly mimeType?: string;
	readonly fileName?: string | undefined;
	readonly urlOrPath?: string;
}

const JSON_EXTENSIONS: ReadonlySet<string> = new Set(["json", "jsonc", "json5", "ndjson"]);

const ARCHIVE_EXTENSIONS: ReadonlySet<string> = new Set([
	"zip",
	"tar",
	"gz",
	"tgz",
	"bz2",
	"tbz2",
	"xz",
	"txz",
	"zst",
	"7z",
	"rar",
]);

const TABLE_MIME_TYPES: ReadonlySet<string> = new Set([
	"text/csv",
	"text/tab-separated-values",
	"application/vnd.ms-excel",
	"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
]);

const DOCUMENT_MIME_TYPES: ReadonlySet<string> = new Set([
	"application/msword",
	"application/vnd.openxmlformats-officedocument.wordprocessingml.document",
]);

const ARCHIVE_MIME_TYPES: ReadonlySet<string> = new Set([
	"application/zip",
	"application/x-zip-compressed",
	"application/gzip",
	"application/x-tar",
	"application/x-bzip2",
	"application/x-xz",
	"application/zstd",
	"application/x-7z-compressed",
	"application/x-rar-compressed",
	"application/vnd.rar",
]);

function classifyMimeType(rawMimeType: string): SandAttachmentKind | null {
	const mime = (rawMimeType.split(";")[0] ?? "").trim().toLowerCase();
	if (mime.startsWith("image/")) return "image";
	if (mime.startsWith("video/")) return "video";
	if (mime.startsWith("audio/")) return "audio";
	if (mime === "application/pdf") return "pdf";
	if (mime === "text/markdown") return "markdown";
	if (TABLE_MIME_TYPES.has(mime)) return "table";
	if (mime === "application/json" || mime.endsWith("+json")) return "json";
	if (DOCUMENT_MIME_TYPES.has(mime)) return "document";
	if (ARCHIVE_MIME_TYPES.has(mime)) return "archive";
	if (mime.startsWith("text/")) return "text";
	return null;
}

function extensionSubject(source: string): string {
	let pathname: string;
	try {
		pathname = new URL(source).pathname;
	} catch {
		return source;
	}
	try {
		return decodeURIComponent(pathname);
	} catch {
		return pathname;
	}
}

function classifyPathLike(source: string): SandAttachmentKind | null {
	const subject = extensionSubject(source);
	const previewKind = getFilePreviewKind(subject);
	switch (previewKind) {
		case "image":
		case "video":
		case "audio":
		case "pdf":
		case "markdown":
		case "table":
			return previewKind;
		case "docx":
			return "document";
		case "json":
			return "json";
		case "text": {
			const ext = attachmentExtension(subject);
			return ext != null && JSON_EXTENSIONS.has(ext) ? "json" : "text";
		}
		case "unknown": {
			const ext = attachmentExtension(subject);
			return ext != null && ARCHIVE_EXTENSIONS.has(ext) ? "archive" : null;
		}
	}
	const _exhaustive: never = previewKind;
	return _exhaustive;
}

// The semantic kind of one attachment: MIME first when available, then the
// original filename, then the URL/path, falling back to the generic "file".
export function classifyAttachment(source: SandAttachmentSource): SandAttachmentKind {
	if (source.mimeType != null && source.mimeType.length > 0) {
		const byMime = classifyMimeType(source.mimeType);
		if (byMime != null) return byMime;
	}
	if (source.fileName != null && source.fileName.length > 0) {
		const byName = classifyPathLike(source.fileName);
		if (byName != null) return byName;
	}
	if (source.urlOrPath != null && source.urlOrPath.length > 0) {
		const byPath = classifyPathLike(source.urlOrPath);
		if (byPath != null) return byPath;
	}
	return "file";
}

// Preserves first-seen order so a mixed summary reads in the order the
// files were attached.
export function countAttachmentKinds(
	kinds: readonly SandAttachmentKind[],
): readonly SandAttachmentKindCount[] {
	const counts = new Map<SandAttachmentKind, number>();
	for (const kind of kinds) {
		counts.set(kind, (counts.get(kind) ?? 0) + 1);
	}
	return [...counts].map(([kind, count]) => ({ kind, count }));
}
